using SanSo.Api;using SanSo.Api.Modules;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddSingleton<DemoStore>();builder.Services.AddSanSoModules();builder.Services.AddSingleton<IdentityService>();builder.Services.AddSingleton<AuditTrail>();builder.Services.AddSingleton<ReliableSync>();builder.Services.AddCors(x=>x.AddDefaultPolicy(p=>p.WithOrigins("http://localhost:5173","http://127.0.0.1:5173","http://127.0.0.1:5174").AllowAnyHeader().AllowAnyMethod()));builder.Services.AddOpenApi();builder.Services.AddRateLimiter(x=>x.AddFixedWindowLimiter("auth",o=>{o.PermitLimit=10;o.Window=TimeSpan.FromMinutes(1);o.QueueLimit=0;}));var app=builder.Build();app.UseMiddleware<SafeProblemMiddleware>();app.UseCors();app.UseRateLimiter();app.MapOpenApi();app.MapIdentity();app.MapSanSoModules();
static string Tenant(HttpRequest r)=>r.Headers["X-Tenant-Id"].FirstOrDefault()??"tenant-an-nhien";
app.MapGet("/health",()=>Results.Ok(new{status="ok"}));app.MapGet("/api/dashboard",(HttpRequest r,DemoStore db)=>Results.Ok(db.Dashboard(Tenant(r))));app.MapGet("/api/orders",(HttpRequest r,DemoStore db)=>Results.Ok(db.Orders(Tenant(r))));app.MapGet("/api/reconciliations/current",(HttpRequest r,DemoStore db)=>Results.Ok(db.Reconcile(Tenant(r))));app.MapPost("/api/imports/demo",(HttpRequest r,DemoStore db)=>Results.Ok(db.ImportDemo(Tenant(r))));app.Run();public partial class Program{}
